import{_t as e,it as t,n,rt as r}from"./chunks/framework.uM88Qy9F.js";var i=JSON.parse(`{"title":"框架简介","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/introduction.md","filePath":"frontend/introduction.md","lastUpdated":1794049926000}`),a={name:`frontend/introduction.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="框架简介" tabindex="-1">框架简介 <a class="header-anchor" href="#框架简介" aria-label="Permalink to “框架简介”">​</a></h1><p>本页说明前端的技术栈、目录结构、模块划分与启动流程，适用于前端开发者。</p><p><code>frontend</code> 基于 Vue、Vite、TypeScript、Pinia、Vue Router、vue-i18n、Tailwind CSS 与 XiHan.UI。运行要求 Node.js 24+、pnpm 11+；仓库不提交锁文件，依赖版本统一写在 <code>pnpm-workspace.yaml</code> 的 <code>catalog</code>。</p><p>前端不手写接口：调用、类型、权限码与推送方法名都由后端导出的契约生成；菜单与路由由后端页面登记下发。</p><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to “目录”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>frontend/</span></span>
<span class="line"><span>├─ contracts/            后端导出的 openapi.json、realtime.json（入库，CI 比对）</span></span>
<span class="line"><span>├─ scripts/              gen-contracts 与门禁脚本（px / token / i18n / modules / permissions）</span></span>
<span class="line"><span>├─ packages/  (~)        壳层与通用能力，不得引用 @/</span></span>
<span class="line"><span>│  ├─ contracts/         生成的契约层 + 手写的分页适配 paging.ts</span></span>
<span class="line"><span>│  ├─ request/           运行时客户端</span></span>
<span class="line"><span>│  ├─ router/            守卫、菜单 → 路由、核心路由、视图解析</span></span>
<span class="line"><span>│  ├─ stores/            会话、权限、偏好、标签栏、壳层扩展等 Pinia store</span></span>
<span class="line"><span>│  ├─ layouts/           前端壳（侧栏、顶栏、标签栏、偏好中心……）</span></span>
<span class="line"><span>│  ├─ components/        公共组件与 SchemaPage</span></span>
<span class="line"><span>│  ├─ composables/  hooks/  utils/  constants/  types/</span></span>
<span class="line"><span>│  ├─ design/            应用令牌、组件库令牌桥与全局样式</span></span>
<span class="line"><span>│  ├─ locales/           壳层文案 × 10 与组件库语言包映射</span></span>
<span class="line"><span>│  ├─ iconify/           离线图标与 IconPicker</span></span>
<span class="line"><span>│  ├─ designers/  printing/   设计器接线与打印</span></span>
<span class="line"><span>│  └─ views/_core/       认证、控制中心、个人中心、OAuth 同意页、关于页、403 / 404 / 500</span></span>
<span class="line"><span>└─ src/  (@)             应用侧</span></span>
<span class="line"><span>   ├─ main.ts  App.vue  app/context.ts  router/  styles/</span></span>
<span class="line"><span>   └─ modules/&lt;包&gt;/      views/**、locales/&lt;区域&gt;.ts × 10、setup.ts</span></span></code></pre></div><table tabindex="0"><thead><tr><th>别名</th><th>指向</th></tr></thead><tbody><tr><td><code>@</code></td><td><code>frontend/src</code></td></tr><tr><td><code>~</code></td><td><code>frontend/packages</code>（如 <code>~/contracts</code>、<code>~/components</code>、<code>~/request</code>、<code>~/stores</code>）</td></tr></tbody></table><p>模块之间不互相引用，共用的东西放 <code>packages/</code>。<code>packages/</code> 反向引用 <code>@/</code> 由 lint 拦截。</p><h2 id="模块" tabindex="-1">模块 <a class="header-anchor" href="#模块" aria-label="Permalink to “模块”">​</a></h2><p><code>src/modules/&lt;包&gt;</code> 与后端能力包同名，页面只放在这里（<code>pnpm modules:check</code> 守护）：</p><table tabindex="0"><thead><tr><th>模块</th><th>页面</th></tr></thead><tbody><tr><td><code>workbench</code></td><td>工作台</td></tr><tr><td><code>identity</code></td><td>用户、在线用户</td></tr><tr><td><code>organization</code></td><td>部门、岗位</td></tr><tr><td><code>tenancy</code></td><td>租户、套餐、我的订阅</td></tr><tr><td><code>access</code></td><td>角色、权限目录、委托、字段安全、访问策略、约束规则、菜单；授权申请的审批单据</td></tr><tr><td><code>settings</code></td><td>参数、字典、业务编号</td></tr><tr><td><code>files</code></td><td>文件库、存储配置、导出中心</td></tr><tr><td><code>notification</code></td><td>通知公告、发送记录、模板、邮件 / 短信 / 机器人 / Telegram 配置、我的消息</td></tr><tr><td><code>auditing</code></td><td>链路追踪；操作、登录、访问、异常、数据变更、权限变更、条件命中、开放接口八个日志页</td></tr><tr><td><code>maintenance</code></td><td>作业、缓存、服务监控、版本、升级记录</td></tr><tr><td><code>openplatform</code></td><td>OAuth 应用</td></tr><tr><td><code>printing</code></td><td>打印模板（设计器、样例数据、预览与直打）</td></tr><tr><td><code>chat</code></td><td>在线聊天（全屏页与顶栏浮动面板）、聊天审计</td></tr><tr><td><code>workflow</code></td><td>流程定义、流程实例、审批中心</td></tr><tr><td><code>codegeneration</code></td><td>代码生成（数据源、表配置、模板、生成历史）</td></tr><tr><td><code>ai</code></td><td>AI 提供商、提示词、知识库、助手</td></tr></tbody></table><p><code>workbench</code>、<code>workflow</code>、<code>printing</code>、<code>codegeneration</code>、<code>chat</code>、<code>ai</code> 是可选模块：后端 <code>BasicApp:Modules:&lt;名&gt;:Enabled</code> 关掉后，页面与权限码都不下发，前端对应入口随之消失。关于页 <code>about/project/index</code> 由壳层提供（<code>packages/views/_core/about</code>）。</p><h2 id="应用启动" tabindex="-1">应用启动 <a class="header-anchor" href="#应用启动" aria-label="Permalink to “应用启动”">​</a></h2><ol><li><code>main.ts</code> 预载离线图标集，创建应用、Pinia 与 i18n；</li><li>依次执行各模块 <code>setup.ts</code> 的默认导出：登记本模块文案（<code>registerModuleLocales</code>），可选模块另登记壳层扩展（<code>registerShellExtension</code>）、看板小组件（<code>registerWorkbenchWidget</code>）或公共包接线（如打印的 <code>configurePrinting</code>），只登记、不发请求；</li><li><code>configureRequest</code> 注入接口前缀、令牌、区域与错误钩子；</li><li>装好当前区域的文案后，<code>registerApplicationContext</code> 向壳层注入接口实现（<code>AppContextApis</code>：登录配置、个人中心、用户设置、收件箱、导入导出、文件、切换租户、模仿等），壳层不直接依赖业务模块；壳层用不到的接口显式抛错，不回空值；</li><li>挂上路由守卫后挂载；守卫首次进入时调 <code>auth.permissions</code>，把菜单树装成动态路由。</li></ol><h2 id="命令" tabindex="-1">命令 <a class="header-anchor" href="#命令" aria-label="Permalink to “命令”">​</a></h2><table tabindex="0"><thead><tr><th>任务</th><th>命令</th></tr></thead><tbody><tr><td>安装</td><td><code>pnpm install --no-frozen-lockfile</code></td></tr><tr><td>开发</td><td><code>pnpm dev</code>（<code>http://localhost:9100</code>；<code>/api</code>、<code>/blobs</code>、<code>/openapi.json</code>、<code>/mcp</code>、<code>/health</code> 与 WebSocket <code>/hubs</code> 代理到 <code>VITE_DEV_PROXY_TARGET</code>，缺省 <code>http://localhost:9710</code>）</td></tr><tr><td>生成契约</td><td><code>pnpm gen:contracts</code></td></tr><tr><td>综合检查</td><td><code>pnpm check</code></td></tr><tr><td>单测</td><td><code>pnpm test</code></td></tr><tr><td>构建</td><td><code>pnpm build</code></td></tr></tbody></table><p>环境变量见 <code>frontend/.env.example</code>；本机改动写 <code>.env.local</code>，不提交。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./development">开发流程</a> · <a href="./request">契约与请求</a> · <a href="./routing">菜单与路由</a></li></ul>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};